// @vitest-environment jsdom
import {beforeEach,afterEach,it,expect,vi} from 'vitest';
import {render,screen,fireEvent,act,cleanup} from '@testing-library/react';
import {ResultViewer} from './ResultViewer';
import type {Execution} from '@/types';
vi.mock('@/lib/i18n',()=>({useLanguage:()=>({language:'en',t:(k:string)=>k})}));
vi.mock('@/lib/analytics',()=>({trackEvent:vi.fn()}));
const make=(id:string):Execution=>({id,templateId:'documentation',templateName:`LOCAL_${id}`,input:{subject:id},intent:id,output:`LOCAL_OUTPUT_${id}`,status:'completed',createdAt:new Date('2026-10-12T00:00:00Z')});
const props=(id:string)=>({execution:make(id),output:`LOCAL_OUTPUT_${id}`,onAccept:vi.fn(),onReject:vi.fn(),onRetry:vi.fn(),onBack:vi.fn(),onFollowUp:vi.fn()});
beforeEach(()=>vi.useFakeTimers());
afterEach(()=>{cleanup();vi.useRealTimers();vi.restoreAllMocks();});
it('retains same-run draft but clears draft for a new execution identity',()=>{
 const a=props('A');const view=render(<ResultViewer {...a}/>);
 fireEvent.change(screen.getByTestId('followup-input'),{target:{value:'LOCAL_A_UNSENT_REFINEMENT'}});
 view.rerender(<ResultViewer {...a} execution={{...a.execution}}/>);
 expect((screen.getByTestId('followup-input') as HTMLTextAreaElement).value).toBe('LOCAL_A_UNSENT_REFINEMENT');
 view.rerender(<ResultViewer {...props('B')}/>);
 expect((screen.getByTestId('followup-input') as HTMLTextAreaElement).value).toBe('');
 expect((screen.getByTestId('followup-submit-btn') as HTMLButtonElement).disabled).toBe(true);
});
it('late clipboard completion for A cannot mark B as copied',async()=>{
 let resolve!:()=>void;
 const writeText=vi.fn(()=>new Promise<void>(r=>{resolve=r}));
 Object.defineProperty(navigator,'clipboard',{value:{writeText},configurable:true});
 const view=render(<ResultViewer {...props('A')}/>);
 fireEvent.click(screen.getByRole('button',{name:/Export/i}));
 fireEvent.click(screen.getByRole('button',{name:/Copy to Clipboard/i}));
 expect(writeText).toHaveBeenCalledTimes(1);
 expect(writeText.mock.calls[0][0]).toContain('LOCAL_OUTPUT_A');
 view.rerender(<ResultViewer {...props('B')}/>);
 await act(async()=>{resolve();await Promise.resolve();});
 expect(screen.queryByRole('button',{name:/Copied!/i})).toBeNull();
});
